'use client';

import { debounce } from '@/functions/debounce';
import { useQuery } from '@tanstack/react-query';
import { parseAsInteger, parseAsString, useQueryState } from 'nuqs';
import { useEffect, useMemo, useState } from 'react';
import { DueDiligenceStatusLiquidacao } from '../enums';
import type { TLiquidationCountsResponse } from '../interfaces/services';
import {
    normalizeLiquidacaoListFilterFromUrl,
    type LiquidacaoFilterType,
} from '../interfaces/store';

function mapLiquidationCountsToTabs(
    api: TLiquidationCountsResponse,
): Record<LiquidacaoFilterType, number> {
    return {
        TODOS: api.todos ?? 0,
        [DueDiligenceStatusLiquidacao.LIQ_APROVADO_RESSALVA]: api.aprovado_ressalva ?? 0,
        [DueDiligenceStatusLiquidacao.LIQ_EM_LIQUIDACAO]: api.em_liquidacao ?? 0,
        [DueDiligenceStatusLiquidacao.LIQ_EM_CESSAO]: api.em_cessao ?? 0,
    };
}

const DEFAULT_COUNTS: Record<LiquidacaoFilterType, number> = {
    TODOS: 0,
    [DueDiligenceStatusLiquidacao.LIQ_APROVADO_RESSALVA]: 0,
    [DueDiligenceStatusLiquidacao.LIQ_EM_LIQUIDACAO]: 0,
    [DueDiligenceStatusLiquidacao.LIQ_EM_CESSAO]: 0,
};

export function useViewModelLiquidacaoFilter() {
    const [urlFilter, setUrlFilter] = useQueryState(
        'liqFilter',
        parseAsString.withDefault('TODOS' as LiquidacaoFilterType),
    );

    const [search, setSearch] = useQueryState('liqSearch', parseAsString.withDefault(''));
    const [localSearch, setLocalSearch] = useState(search ?? '');
    const [, setLiqPage] = useQueryState('liqPage', parseAsInteger.withDefault(1));
    const filter = normalizeLiquidacaoListFilterFromUrl(urlFilter);

    const { data: countsData, isLoading } = useQuery<TLiquidationCountsResponse>({
        queryKey: ['due-diligence', 'liquidacao-counts'],
        enabled: false,
    });

    const tabs: { id: LiquidacaoFilterType; label: string }[] = [
        { id: 'TODOS', label: 'Todos' },
        { id: DueDiligenceStatusLiquidacao.LIQ_APROVADO_RESSALVA, label: 'Aprovado c/ ressalva' },
        { id: DueDiligenceStatusLiquidacao.LIQ_EM_LIQUIDACAO, label: 'Em liquidação' },
        { id: DueDiligenceStatusLiquidacao.LIQ_EM_CESSAO, label: 'Em cessão' },
    ];

    const counts = useMemo(
        () => (countsData ? mapLiquidationCountsToTabs(countsData) : DEFAULT_COUNTS),
        [countsData],
    );

    function handleFilterChange(newFilter: LiquidacaoFilterType) {
        setUrlFilter(newFilter);
        void setLiqPage(1);
    }

    const debouncedSetSearch = useMemo(
        () =>
            debounce((value: string) => {
                void setSearch(value === '' ? null : value);
                void setLiqPage(1);
            }, 1000),

